    .reg .f32 %f_total;
    .reg .f32 %f_nf;
    .reg .f32 %f_mean;
    .reg .f32 %f_diff;
    .reg .f32 %f_sq;
    .reg .f32 %f_var;
    .reg .f32 %f_vareps;
    .reg .f32 %f_std;
    .reg .f32 %f_invstd;
    .reg .u64 %rd_idx2_64;
    .reg .u64 %rd_off2;
    .reg .u64 %rd_addr_in2;
    .reg .u64 %rd_addr_out2;
    .reg .u64 %rd_addr_w2;
