    .reg .f32 %f_w;
    .reg .f32 %f_bv;
    .reg .f32 %f_norm;
    .reg .f32 %f_out;
    .reg .pred %p4;
    .reg .u32 %r_nvec;
    .reg .u32 %r_rem;
    .reg .u32 %r_vidx;
    .reg .f32 %f_v0;
    .reg .f32 %f_v1;
    .reg .f32 %f_v2;
    .reg .f32 %f_v3;
    .reg .f32 %f_w0;
    .reg .f32 %f_w1;
    .reg .f32 %f_w2;
    .reg .f32 %f_w3;
    .reg .f32 %f_b0;
    .reg .f32 %f_b1;
    .reg .f32 %f_b2;
    .reg .f32 %f_b3;
    .reg .f32 %f_o0;
    .reg .f32 %f_o1;
    .reg .f32 %f_o2;
