    ld.param.u64 %rd_in, [input_ptr];
    ld.param.u64 %rd_out, [output_ptr];
    ld.param.u64 %rd_w, [weight_ptr];
    ld.param.u64 %rd_b, [bias_ptr];
    ld.param.u32 %r_n, [n_elements];
    cvta.to.global.u64 %rd_in, %rd_in;
    cvta.to.global.u64 %rd_out, %rd_out;
    cvta.to.global.u64 %rd_w, %rd_w;
    cvta.to.global.u64 %rd_b, %rd_b;
    mov.u32 %r_bid, %ctaid.x;
    mov.u32 %r_tid, %tid.x;
    mov.u32 %r_ntid, %ntid.x;
    cvt.u64.u32 %rd_bid64, %r_bid;
    cvt.u64.u32 %rd_n64, %r_n;
    mul.lo.u64 %rd_batch_off, %rd_bid64, %rd_n64;
    mul.lo.u64 %rd_batch_byteoff, %rd_batch_off, 4;
    add.u64 %rd_in_base, %rd_in, %rd_batch_byteoff;
    add.u64 %rd_out_base, %rd_out, %rd_batch_byteoff;
