    and.b32 %r_rem, %r_n, 3;
    // ---- Pass 1: compute sum (vectorized) ----
    mov.f32 %f_sum, 0f00000000;
    mov.u32 %r_vidx, %r_tid;
p1v_loop:
    setp.ge.u32 %p1, %r_vidx, %r_nvec;
    @%p1 bra p1v_loop_end;
    cvt.u64.u32 %rd_idx64, %r_vidx;
    shl.b64 %rd_off, %rd_idx64, 4;
    add.u64 %rd_addr, %rd_in_base, %rd_off;
    ld.global.v4.f32 {%f_v0, %f_v1, %f_v2, %f_v3}, [%rd_addr];
    add.f32 %f_sum, %f_sum, %f_v0;
    add.f32 %f_sum, %f_sum, %f_v1;
    add.f32 %f_sum, %f_sum, %f_v2;
    add.f32 %f_sum, %f_sum, %f_v3;
    add.u32 %r_vidx, %r_vidx, %r_ntid;
    bra p1v_loop;
p1v_loop_end:
    cvt.u64.u32 %rd_idx64, %r_nvec;
    shl.b64 %rd_off, %rd_idx64, 4;
    add.u64 %rd_addr, %rd_in_base, %rd_off;
    setp.ge.u32 %p1, %r_tid, %r_rem;
