    cvt.u64.u32 %rd_tid64, %r_tid;
    mul.lo.u64 %rd_off, %rd_tid64, 4;
    add.u64 %rd_addr, %rd_addr, %rd_off;
    ld.global.f32 %f_val, [%rd_addr];
    sub.f32 %f_diff, %f_val, %f_mean;
    mul.f32 %f_sq, %f_diff, %f_diff;
    add.f32 %f_sum, %f_sum, %f_sq;
p2_tail_skip:
    cvt.u64.u32 %rd_tid64, %r_tid;
    mul.lo.u64 %rd_tidoff, %rd_tid64, 4;
    add.u64 %rd_sh_addr, %rd_sh_base, %rd_tidoff;
    st.shared.f32 [%rd_sh_addr], %f_sum;
    bar.sync 0;
    mov.u32 %r_stride, 512;
p2_red:
    setp.eq.u32 %p2, %r_stride, 0;
    @%p2 bra p2_red_end;
    setp.lt.u32 %p3, %r_tid, %r_stride;
    @!%p3 bra p2_red_skip;
    add.u32 %r_tid_stride, %r_tid, %r_stride;
    cvt.u64.u32 %rd_tidstride64, %r_tid_stride;
    mul.lo.u64 %rd_tidstride_off, %rd_tidstride64, 4;
    add.u64 %rd_sh_addr2, %rd_sh_base, %rd_tidstride_off;
    ld.shared.f32 %f_other, [%rd_sh_addr2];
    ld.shared.f32 %f_my, [%rd_sh_addr];
    add.f32 %f_newval, %f_my, %f_other;
    st.shared.f32 [%rd_sh_addr], %f_newval;
p2_red_skip:
    bar.sync 0;
    shr.u32 %r_stride, %r_stride, 1;
    bra p2_red;
p2_red_end:
    ld.shared.f32 %f_total, [%rd_sh_base];
    div.rn.f32 %f_var, %f_total, %f_nf;
    add.f32 %f_vareps, %f_var, 0f3727C5AC;
    sqrt.rn.f32 %f_std, %f_vareps;
    rcp.rn.f32 %f_invstd, %f_std;
    bar.sync 0;
    // ---- Pass 3: normalize (vectorized) ----
    mov.u32 %r_vidx, %r_tid;
p3v_loop:
    setp.ge.u32 %p4, %r_vidx, %r_nvec;
    @%p4 bra p3v_loop_end;
    cvt.u64.u32 %rd_idx2_64, %r_vidx;
    shl.b64 %rd_off2, %rd_idx2_64, 4;
    add.u64 %rd_addr_in2, %rd_in_base, %rd_off2;
    add.u64 %rd_addr_out2, %rd_out_base, %rd_off2;
    add.u64 %rd_addr_w2, %rd_w, %rd_off2;
    add.u64 %rd_addr_b2, %rd_b, %rd_off2;
    ld.global.v4.f32 {%f_v0, %f_v1, %f_v2, %f_v3}, [%rd_addr_in2];
    ld.global.v4.f32 {%f_w0, %f_w1, %f_w2, %f_w3}, [%rd_addr_w2];
    ld.global.v4.f32 {%f_b0, %f_b1, %f_b2, %f_b3}, [%rd_addr_b2];
