    sub.f32 %f_diff, %f_v1, %f_mean;
    mul.f32 %f_norm, %f_diff, %f_invstd;
    fma.rn.f32 %f_o1, %f_norm, %f_w1, %f_b1;
    sub.f32 %f_diff, %f_v2, %f_mean;
    mul.f32 %f_norm, %f_diff, %f_invstd;
    fma.rn.f32 %f_o2, %f_norm, %f_w2, %f_b2;
    sub.f32 %f_diff, %f_v3, %f_mean;
    mul.f32 %f_norm, %f_diff, %f_invstd;
    fma.rn.f32 %f_o3, %f_norm, %f_w3, %f_b3;
    st.global.v4.f32 [%rd_addr_out2], {%f_o0, %f_o1, %f_o2, %f_o3};
    add.u32 %r_vidx, %r_vidx, %r_ntid;
    bra p3v_loop;
