    @%p4 bra p3_tail_skip;
    add.u64 %rd_addr_in2, %rd_in_base, %rd_off2;
    add.u64 %rd_addr_out2, %rd_out_base, %rd_off2;
    add.u64 %rd_addr_w2, %rd_w, %rd_off2;
    add.u64 %rd_addr_b2, %rd_b, %rd_off2;
    cvt.u64.u32 %rd_tid64, %r_tid;
    mul.lo.u64 %rd_off, %rd_tid64, 4;
    add.u64 %rd_addr_in2, %rd_addr_in2, %rd_off;
    add.u64 %rd_addr_out2, %rd_addr_out2, %rd_off;
    add.u64 %rd_addr_w2, %rd_addr_w2, %rd_off;
    add.u64 %rd_addr_b2, %rd_addr_b2, %rd_off;
    ld.global.f32 %f_x, [%rd_addr_in2];
    ld.global.f32 %f_w, [%rd_addr_w2];
    ld.global.f32 %f_bv, [%rd_addr_b2];
    sub.f32 %f_diff, %f_x, %f_mean;
    mul.f32 %f_norm, %f_diff, %f_invstd;
    fma.rn.f32 %f_out, %f_norm, %f_w, %f_bv;
    st.global.f32 [%rd_addr_out2], %f_out;
