class ModelNew(nn.Module):
    """
    Simple model that performs Layer Normalization using a custom PTX kernel.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Kernel supports float32 only"

        x = x.contiguous()
        weight = self.weight.contiguous()
        bias = self.bias.contiguous()

        batch_size = x.shape[0]
        n_elements = x.numel() // batch_size

        output = torch.empty_like(x)

        module = _get_ptx_module()
        module.launch(
            "layernorm_kernel",
            grid=(batch_size, 1, 1),
            block=(1024, 1, 1),
            arguments=[x, output, weight, bias, i32(n_elements)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return output
